import React, { useRef, Suspense, useState, useMemo, useEffect} from 'react';
import ReactPlayer from 'react-player';
import '../player.css'


const VideoRender = ({ data, videoIndex}) => {
    const videoRef = useRef(null);
    const [videoLoaded, setVideoLoaded] = useState(false);

    const handleVideoLoaded = () => {
        console.log('video loaded')
        setVideoLoaded(true);
    };

    const handleVideoWaiting = () => {
        console.log('waiting')
        setVideoLoaded(false);
    };
    // Memoize video element
    const videoElement = useMemo(() => {
        if (data) {
        return (
            <>
                {/* Show loader if video is not loaded */}
                {/* {!videoLoaded && (
                    <div>
                        <img src={logo} className='w-[5%] h-[5%]' alt="Loader" />
                    </div>
                )} */}
                {
                    data.map((videoLink, index) => (
                        <div className={`${videoIndex == index ? "" : "video-bg"} ${'w-[100%] h-[100%] react-player object-cover'}`} >
                            <ReactPlayer playing muted loop playsinline url={videoLink.redirectLink} width="100%" height="100%"
                                config={{
                                    playerOptions: {
                                        responsive: true,
                                        fullscreen: true,
                                        playsinline: true
                                }
                                }}>
                            </ReactPlayer>
                        </div>
                    ))
                }
            </>
        );
        }
        return null;
    }, [data, videoIndex]);

  return videoElement;
};

export default VideoRender;